struct OrderRow: FetchableRecord, TableRecord, Decodable {
    static let databaseTableName = "orders"
    var id: Int64
    var due: Date
    var total: Decimal
}

func overdueOrders(_ db: Database, asOf: Date) throws -> [OrderRow] {
    try OrderRow.filter(Column("due") < asOf).fetchAll(db)   // [OrderRow] is the record set
}
